"use client"

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 */

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import { deskInitials } from "@/lib/inbox"
import { groupMessages, presenceDotStyle, type ThreadMessageData } from "@/lib/thread-desk"
import { MessageBubble } from "@/components/ui/message-bubble"
import { MessageCardFile } from "@/components/ui/message-card-file"
import { MessageCardInvoice } from "@/components/ui/message-card-invoice"
import { MessageCardMetric } from "@/components/ui/message-card-metric"
import { TypingIndicator } from "@/components/ui/typing-indicator"

export type ChatThreadProps = {
  label: string
  title?: string
  status?: string
  presence?: "online" | "offline" | "away"
  messages?: readonly ThreadMessageData[]
  typing?: { names: readonly string[]; label?: string }
  onRetryMessage?: (id: string) => void
  retryLabel?: string
  state?: "ready" | "loading" | "empty" | "error"
  emptyLabel?: string
  loadingLabel?: string
  error?: string
  onRetry?: () => void
  actions?: ReactNode
  className?: string
}

export function ChatThread({
  label,
  title,
  status,
  presence,
  messages = [],
  typing,
  onRetryMessage,
  retryLabel = "Reintentar",
  state = "ready",
  emptyLabel = "Aún no hay mensajes",
  loadingLabel = "Cargando el hilo",
  error,
  onRetry,
  actions,
  className,
}: ChatThreadProps) {
  const grouped = groupMessages(messages)
  return (
    <section data-slot="chat-thread" className={cn("flex min-h-0 min-w-0 flex-1 flex-col", className)}>
      <header className="flex items-center gap-3 border-b border-border px-1 py-3">
        <span className="relative grid size-10 place-items-center rounded-full bg-foreground text-xs font-medium text-background" aria-hidden>
          {title ? deskInitials(title) : "?"}
          {presence ? (
            <span
              data-presence={presence}
              className="absolute end-0 bottom-0 size-2.5 rounded-full ring-2 ring-background"
              style={presenceDotStyle(presence)}
            />
          ) : null}
        </span>
        <span className="min-w-0 flex-1">
          {title ? <span className="block truncate text-sm font-semibold">{title}</span> : null}
          {status ? <span className="block truncate text-xs text-muted-foreground">{status}</span> : null}
        </span>
        {actions}
      </header>
      {state === "loading" ? (
        <div role="status" aria-label={loadingLabel} className="grid flex-1 gap-3 p-4">
          <span className="h-12 w-2/3 animate-pulse rounded-2xl bg-muted" />
          <span className="ms-auto h-12 w-1/2 animate-pulse rounded-2xl bg-muted" />
        </div>
      ) : null}
      {state === "error" ? (
        <div role="alert" className="m-4 grid gap-2 rounded-2xl border border-border p-3">
          <p className="text-sm text-destructive">{error}</p>
          {onRetry ? (
            <button type="button" className="h-11 justify-self-start rounded-full px-3 text-sm text-primary" onClick={onRetry}>
              {retryLabel}
            </button>
          ) : null}
        </div>
      ) : null}
      {state === "ready" ? (
        <div role="log" aria-live="polite" aria-relevant="additions" aria-label={label} className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto px-1 py-4">
          {grouped.length === 0 ? <p className="text-sm text-muted-foreground">{emptyLabel}</p> : null}
          {grouped.map((message) => (
            <div key={message.id} className="grid gap-2">
              {message.body ? (
                <MessageBubble
                  side={message.side}
                  author={message.author}
                  time={message.time}
                  delivery={message.delivery}
                  deliveryLabel={message.deliveryLabel}
                  grouped={message.grouped}
                  enter={message.enter}
                  onRetry={message.delivery === "failed" ? () => onRetryMessage?.(message.id) : undefined}
                  retryLabel={retryLabel}
                >
                  {message.body}
                </MessageBubble>
              ) : null}
              {message.note ? (
                <div className="max-w-md rounded-2xl border border-border bg-card p-3">
                  <p className="text-sm font-medium">{message.note.title}</p>
                  <p className="text-xs text-muted-foreground">{message.note.detail}</p>
                  {message.note.body ? <p className="mt-2 text-sm">{message.note.body}</p> : null}
                </div>
              ) : null}
              {message.file ? <MessageCardFile name={message.file.name} detail={message.file.detail} status={message.file.status} /> : null}
              {message.invoice ? <MessageCardInvoice title={message.invoice.title} amount={message.invoice.amount} due={message.invoice.due} /> : null}
              {message.metric ? (
                <MessageCardMetric
                  title={message.metric.title}
                  chip={message.metric.chip}
                  value={message.metric.value}
                  caption={message.metric.caption}
                  filled={message.metric.filled}
                  total={message.metric.total}
                  start={message.metric.start}
                  end={message.metric.end}
                />
              ) : null}
            </div>
          ))}
          {typing?.names?.length ? (
            <TypingIndicator names={typing.names} label={() => typing.label ?? ""} dots />
          ) : null}
        </div>
      ) : null}
    </section>
  )
}

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * Tipos y puertos. Sin red, sin Supabase y sin dominio de un canal.
 */

import type { CSSProperties, ReactNode } from "react"

import { foldInboxText, type DeskPresence } from "@/lib/inbox"

/** Online uses the host success token, then chart-2. It is not the accent. */
export function presenceDotStyle(presence: DeskPresence): CSSProperties {
  if (presence === "online") return { backgroundColor: "var(--success, var(--chart-2))" }
  if (presence === "offline") return { backgroundColor: "var(--muted-foreground)" }
  return { backgroundColor: "var(--accent-foreground)" }
}

export type ThreadStatus = "ready" | "loading" | "empty" | "error" | "offline"

export type ThreadFilter = {
  value: string
  label: string
}

export type ConversationSection = {
  id: string
  label: string
  hint?: string
}

export type ConversationItemData = {
  id: string
  title: string
  preview?: string
  time?: string
  unread?: number
  section?: string
  tags?: readonly string[]
  presence?: DeskPresence
  role?: string
  kind?: "thread" | "contact"
  stage?: string
  windowLabel?: string
  channel?: ReactNode
}

export type DeliveryState = "sending" | "sent" | "delivered" | "read" | "failed"

export type ThreadNote = {
  title: string
  detail: string
  body?: string
}

export type ThreadFile = {
  name: string
  detail: string
  status?: string
}

export type ThreadInvoice = {
  title: string
  amount: string
  due: string
}

export type ThreadMetric = {
  title: string
  chip?: string
  value: string
  caption?: string
  filled: number
  total: number
  start: string
  end: string
}

export type ThreadMessageData = {
  id: string
  side: "incoming" | "outgoing"
  author: string
  time?: string
  body?: string
  delivery?: DeliveryState
  deliveryLabel?: string
  grouped?: "single" | "start" | "middle" | "end"
  enter?: boolean
  note?: ThreadNote
  file?: ThreadFile
  invoice?: ThreadInvoice
  metric?: ThreadMetric
}

export type SuggestionItem = {
  id: string
  label: string
}

export type SecretField = {
  id: string
  label: string
  masked: string
  revealed: string
}

export type PartyFact = {
  id: string
  label: string
  value: string
}

export type PartyMember = {
  id: string
  name: string
  role: string
}

export type PartyFile = {
  id: string
  name: string
  detail: string
}

export type PartyDeal = {
  title: string
  status: string
  amount: string
  value: number
  label: string
}

export type PartyPanelData = {
  name: string
  meta?: string
  deal?: PartyDeal
  facts?: readonly PartyFact[]
  members?: readonly PartyMember[]
  files?: readonly PartyFile[]
  secrets?: readonly SecretField[]
}

export function matchesConversation(item: ConversationItemData, filter: string | undefined, query: string) {
  if (filter && filter !== "all") {
    const tagged = item.tags?.includes(filter) || (filter === "unread" && (item.unread ?? 0) > 0)
    if (!tagged) return false
  }
  const needle = query.trim()
  if (!needle) return true
  const hay = [item.title, item.preview, item.role, item.stage, item.windowLabel].filter(Boolean).join(" ")
  return foldInboxText(hay).includes(foldInboxText(needle))
}

export function groupMessages(messages: readonly ThreadMessageData[]): ThreadMessageData[] {
  return messages.map((message, index) => {
    if (message.grouped) return message
    const prev = messages[index - 1]
    const next = messages[index + 1]
    const same = (other?: ThreadMessageData) =>
      Boolean(other && other.side === message.side && other.author === message.author && !other.file && !other.invoice && !other.metric && !message.file && !message.invoice && !message.metric)
    const before = same(prev)
    const after = same(next)
    const grouped = before && after ? "middle" : before ? "end" : after ? "start" : "single"
    return { ...message, grouped }
  })
}

/**
 * Shared types for the desk pieces. No fetching, no theme.
 * Dates are calendar days (`YYYY-MM-DD`). The host owns locale and timezone.
 */

export const DESK_PRESENCES = ["online", "offline", "away"] as const

export type DeskPresence = (typeof DESK_PRESENCES)[number]

export type DeskMessage = {
  id: string
  author: string
  body: string
  /** Preformatted time. */
  time: string
  side: "incoming" | "outgoing"
  note?: boolean
  receipt?: "seen" | "unseen"
}

export type DeskOption = {
  value: string
  label: string
}

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/

export function foldInboxText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function isCalendarDate(value: string | undefined): value is string {
  return Boolean(value && DATE_RE.test(value))
}

/** True when `due` is a calendar day before `today`. */
export function isOverdueDate(due: string | undefined, today: string): boolean {
  if (!isCalendarDate(due) || !isCalendarDate(today)) return false
  return due < today
}

export function formatDeskDate(iso: string, locale?: string): string {
  if (!isCalendarDate(iso)) return iso
  const [year, month, day] = iso.split("-").map(Number)
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeZone: "UTC" }).format(
    new Date(Date.UTC(year, month - 1, day)),
  )
}

export function deskInitials(name: string): string {
  const letters = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
  return letters || "?"
}
